import{_ as e,c as t,o as n,a4 as a}from"./chunks/framework.ttppV29E.js";const s="/assets/delegate-exchange-create.lFVmH3Fx.png",i="/assets/delegate-exchange-use.CVBkcAG3.png",b=JSON.parse('{"title":"Delegate Exchange","description":"","frontmatter":{},"headers":[],"relativePath":"docs/connections/delegate-exchange.md","filePath":"docs/connections/delegate-exchange.md","lastUpdated":1791474926000}'),o={name:"docs/connections/delegate-exchange.md"},r=a('<h1 id="delegate-exchange" tabindex="-1">Delegate Exchange <a class="header-anchor" href="#delegate-exchange" aria-label="Permalink to &quot;Delegate Exchange&quot;">​</a></h1><p>The Delegate Exchange connection lets an endpoint call a downstream API <strong>as the user who called the endpoint</strong>. It takes the caller&#39;s own access token and exchanges it at AireIdentity for a new token, scoped to the downstream API, using the OAuth 2.0 Token Exchange grant (<a href="https://datatracker.ietf.org/doc/html/rfc8693" target="_blank" rel="noreferrer">RFC 8693</a>).</p><p>The exchanged token still identifies the original user (<code>sub</code>), so the downstream API can apply its own per-user access rules.</p><h2 id="why-use-it" tabindex="-1">Why use it <a class="header-anchor" href="#why-use-it" aria-label="Permalink to &quot;Why use it&quot;">​</a></h2><p>When an endpoint is protected with <a href="/docs/endpoint-authentication/openid-connect-bearer-token.html">Open ID Connect Bearer Token</a> authentication, the caller&#39;s token is available as <code>request.userToken</code>. You could forward that token unchanged, but this is usually the wrong choice:</p><table><thead><tr><th></th><th>Forward <code>request.userToken</code></th><th>Delegate Exchange</th></tr></thead><tbody><tr><td><strong>Audience</strong></td><td>Issued for AireGlu (or the MCP server), so a well-configured downstream API should reject it</td><td>Issued for the downstream API</td></tr><tr><td><strong>Scope</strong></td><td>Whatever the caller&#39;s app asked for, often broader than needed</td><td>Only the Target Scope you request</td></tr><tr><td><strong>Blast radius</strong></td><td>A leaked token works anywhere the original token works</td><td>A leaked token only works against one downstream API</td></tr><tr><td><strong>Downstream identity</strong></td><td>User</td><td>User (<code>sub</code> preserved), with AireGlu as the authorised exchanging client</td></tr></tbody></table><p>Compared to the other connection types:</p><table><thead><tr><th>Connection</th><th>Token represents</th><th>Use when</th></tr></thead><tbody><tr><td><a href="/docs/connections/client-credentials.html">Client Credentials</a></td><td>AireGlu as an application</td><td>The downstream call doesn&#39;t depend on who the user is</td></tr><tr><td><a href="/docs/connections/jwt-bearer.html">JWT Bearer</a></td><td>AireGlu as an application (signed assertion)</td><td>As above, where the provider requires the JWT Bearer grant</td></tr><tr><td><strong>Delegate Exchange</strong></td><td>The calling user, via AireGlu</td><td>The downstream API must know who the user is and enforce their access</td></tr></tbody></table><p>Typical uses:</p><ul><li>An AireFrame widget calls an AireGlu endpoint, which reads records from an API that only returns what the signed-in clinician may see.</li><li>An <a href="/docs/mcp-servers/permissions.html">MCP tool</a> fetches data on behalf of the person using the AI assistant, not with a shared service account.</li></ul><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A client is registered in AireIdentity for AireGlu to exchange tokens with: <ul><li>The <strong>Token Exchange</strong> grant type is enabled.</li><li>The downstream API&#39;s scope is in its allowed scopes.</li><li>It has a client secret.</li></ul></li><li>The caller&#39;s token must be allowed to be exchanged. In AireIdentity this means it carries the <code>delegate_exchange</code> scope, so the calling application must request it at sign-in.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Ask your AireIdentity administrator to set up the exchange client. It is a separate client from the one the calling application uses to sign users in.</p></div><h2 id="creating-a-delegate-exchange-connection" tabindex="-1">Creating a Delegate Exchange Connection <a class="header-anchor" href="#creating-a-delegate-exchange-connection" aria-label="Permalink to &quot;Creating a Delegate Exchange Connection&quot;">​</a></h2><ol><li>Go to the <strong>Connections</strong> section in AireGlu.</li><li>Click the <strong>Add</strong> button.</li><li>Select <strong>Delegate Exchange</strong> as the connection you want to create.</li><li>Under <strong>Connection Details</strong>, fill in: <ul><li><strong>Key</strong>: A unique identifier for this connection (e.g. <code>patient-records-delegate</code>). This can&#39;t be changed after creation.</li><li><strong>Display Name</strong>: A friendly name for easy reference.</li><li><strong>Client ID</strong>: The ID of the exchange client registered in AireIdentity.</li></ul></li><li>Under <strong>Credential</strong>, select the <strong>Client Secret</strong>. This is an AireGlu <a href="/docs/getting-started/secrets.html">secret</a> that holds the exchange client&#39;s secret. Only client secrets are supported; Private Key JWT is not available for this connection type.</li><li>Under <strong>Scope &amp; Authority</strong>, optionally set: <ul><li><strong>Target Scope</strong>: The scope to request for the exchanged token (e.g. <code>PatientRecordsApi</code>). Tasks can override it.</li><li><strong>Authority</strong>: Leave blank to use AireGlu&#39;s AireIdentity instance. Only set it if the exchange must happen at a different identity provider. The caller&#39;s token must have been issued by that same authority.</li></ul></li><li>Click <strong>Save connection</strong>.</li></ol><p><img src="'+s+'" alt="Create Delegate Exchange Connection"></p><h2 id="using-a-delegate-exchange-connection-in-http-request-tasks" tabindex="-1">Using a Delegate Exchange Connection in HTTP Request Tasks <a class="header-anchor" href="#using-a-delegate-exchange-connection-in-http-request-tasks" aria-label="Permalink to &quot;Using a Delegate Exchange Connection in HTTP Request Tasks&quot;">​</a></h2><p>Unlike other connection types, a Delegate Exchange connection has <strong>no default parameters</strong>. The task must say which token to exchange.</p><ol><li>In your endpoint, add or edit an <strong>HTTP Request Task</strong>.</li><li>Go to the <strong>Authorisation</strong> tab.</li><li>Set <strong>Auth Type</strong> to <strong>OAuth Connection</strong>.</li><li>Search and select your Delegate Exchange connection under <strong>Connection Key</strong>.</li><li>Under <strong>Parameters</strong>, click <strong>Add Parameter</strong> and add:</li></ol><table><thead><tr><th>Parameter</th><th>Required</th><th>Value</th></tr></thead><tbody><tr><td><code>subject_token</code></td><td>Yes</td><td>The token to exchange, normally <span><code>{{ request.userToken }}</code></span></td></tr><tr><td><code>scope</code></td><td>No</td><td>Overrides the connection&#39;s <strong>Target Scope</strong> for this task</td></tr></tbody></table><p><img src="'+i+`" alt="Use Delegate Exchange Connection in HTTP Request Task"></p><p>When the task runs, AireGlu:</p><ol><li><p>Renders the <code>subject_token</code> and <code>scope</code> parameters (Liquid, variables and secrets are resolved).</p></li><li><p>Sends a token exchange request to the authority&#39;s token endpoint (found from its <code>/.well-known/openid-configuration</code>):</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;token endpoint&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/x-www-form-urlencoded</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">grant_type=urn:ietf:params:oauth:grant-type:token-exchange</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client_id=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;Client ID&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client_secret=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;Client Secret&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scope=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;scope&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">subject_token=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;subject_token&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">subject_token_type=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">urn:ietf:params:oauth:token-type:access_token</span></span></code></pre></div></li><li><p>Adds the exchanged token to the request as <code>Authorization: Bearer &lt;token&gt;</code>.</p></li><li><p>Caches the exchanged token until it expires. The cache is per user token, scope and client, so one user&#39;s token is never reused for another.</p></li></ol><p>Parameters other than <code>subject_token</code> and <code>scope</code> are ignored for this connection type.</p><h2 id="liquid-mapping" tabindex="-1">Liquid mapping <a class="header-anchor" href="#liquid-mapping" aria-label="Permalink to &quot;Liquid mapping&quot;">​</a></h2><p>Parameter values are Liquid templates, so the subject token and scope can come from the request.</p><h3 id="subject-token" tabindex="-1">Subject token <a class="header-anchor" href="#subject-token" aria-label="Permalink to &quot;Subject token&quot;">​</a></h3><div class="language-liquid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">liquid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">request</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.userToken }}</span></span></code></pre></div><p><code>request.userToken</code> holds the caller&#39;s validated access token. It is only populated when the endpoint is authenticated with <a href="/docs/endpoint-authentication/openid-connect-bearer-token.html">Open ID Connect Bearer Token</a>, and that also covers endpoints called as <a href="/docs/mcp-servers/permissions.html">MCP tools</a>. Otherwise it is empty and the task fails with <em>&quot;Task is missing a &#39;subject_token&#39; parameter&quot;</em>.</p><h3 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><p>The scope is resolved in this order:</p><ol><li>The task&#39;s <code>scope</code> parameter, if it renders to a non-empty value</li><li>The connection&#39;s <strong>Target Scope</strong></li><li>Neither set: the task fails with <em>&quot;No target scope resolvable for this Delegate Exchange connection&quot;</em></li></ol><p>To request the same scope the endpoint is <a href="/docs/endpoint-authentication/permission-gating.html">permission gated</a> on, reference the configured Target Scopes:</p><div class="language-liquid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">liquid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ authentication.targetScopes[0] }}</span></span></code></pre></div><p>or, for more than one scope:</p><div class="language-liquid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">liquid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ authentication.targetScopes | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">join:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39; &#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}</span></span></code></pre></div><p>This keeps the gate (&quot;may this user call the endpoint?&quot;) and the downstream token (&quot;what may AireGlu do for them?&quot;) pointing at the same application. Change the Target Scope in one place and both follow.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Add a Target Scope with <strong>no permissions</strong> to an endpoint&#39;s Open ID Connect Bearer Token method to make it available in <code>authentication.targetScopes</code> without gating on it.</p></div><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h3><p>An endpoint gated on <code>PatientRecordsApi</code> with <code>read:patient</code>, calling the records API as the user:</p><table><thead><tr><th>Setting</th><th>Value</th></tr></thead><tbody><tr><td>Endpoint authentication</td><td>Open ID Connect Bearer Token, Target Scope <code>PatientRecordsApi</code>, permission <code>read:patient</code></td></tr><tr><td>Connection</td><td>Delegate Exchange <code>patient-records-delegate</code>, Target Scope blank</td></tr><tr><td>Task parameter <code>subject_token</code></td><td><span><code>{{ request.userToken }}</code></span></td></tr><tr><td>Task parameter <code>scope</code></td><td><span><code>{{ authentication.targetScopes[0] }}</code></span></td></tr></tbody></table><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><ul><li><strong>Exchange, don&#39;t forward.</strong> Use Delegate Exchange instead of <span><code>Authorization: Bearer {{ request.userToken }}</code></span> when calling anything other than another AireGlu endpoint that expects the same token. Forwarding hands the downstream system a token that wasn&#39;t issued for it.</li><li><strong>Request the narrowest scope.</strong> Use one Target Scope per downstream API. Avoid reusing one connection with a broad scope across unrelated APIs. Create one connection per downstream API, or override <code>scope</code> per task.</li><li><strong>One exchange client per purpose.</strong> Register a dedicated AireIdentity client for exchange, with only the scopes it needs. Don&#39;t reuse the calling application&#39;s sign-in client.</li><li><strong>Keep secrets in Secrets.</strong> The client secret must be an AireGlu secret reference. Never put the secret, or <code>request.userToken</code>, into a response, audit output or log message.</li><li><strong>Combine with permission gating.</strong> <a href="/docs/endpoint-authentication/permission-gating.html">Permission gating</a> stops unauthorised users before any exchange happens. Delegate Exchange then gives the downstream API the user&#39;s identity for its own data-level checks. Neither replaces the downstream API&#39;s own authorisation.</li><li><strong>Leave Authority blank unless you need it.</strong> The subject token and the exchange must come from the same identity provider. Overriding Authority only works if the caller&#39;s token was issued there.</li><li><strong>Don&#39;t use it for non-user traffic.</strong> Jobs, receivers and other calls with no signed-in user have no token to exchange. Use <a href="/docs/connections/client-credentials.html">Client Credentials</a> for those.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>A failed exchange fails the HTTP Request Task with <em>&quot;Failed to make request to endpoint at … - …&quot;</em>, followed by the reason.</p><table><thead><tr><th>Message / symptom</th><th>Things to check</th></tr></thead><tbody><tr><td><em>Task is missing a &#39;subject_token&#39; parameter</em></td><td>Add a <code>subject_token</code> parameter. If it is already <span><code>{{ request.userToken }}</code></span>, the endpoint isn&#39;t using Open ID Connect Bearer Token authentication, or the request wasn&#39;t authenticated with it.</td></tr><tr><td><em>No target scope resolvable</em></td><td>Set <strong>Target Scope</strong> on the connection or a <code>scope</code> task parameter. If you use <code>authentication.targetScopes</code>, check the endpoint has Target Scopes configured (it is empty in Preview).</td></tr><tr><td><em>Delegate token exchange failed: Bad Request</em></td><td>Check the exchange client has the Token Exchange grant enabled and the requested scope allowed. Check the caller&#39;s token includes the <code>delegate_exchange</code> scope and hasn&#39;t expired.</td></tr><tr><td><em>Delegate token exchange failed: Unauthorized</em></td><td>Check <strong>Client ID</strong> and the <strong>Client Secret</strong> secret value.</td></tr><tr><td>Downstream API returns 401</td><td>Check the downstream API accepts tokens for the requested scope and audience.</td></tr><tr><td>Works for one user, not another</td><td>The exchanged token carries the user&#39;s identity. Check that user&#39;s access in the downstream system.</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/endpoint-authentication/openid-connect-bearer-token.html">Open ID Connect Bearer Token</a>: makes <code>request.userToken</code> available</li><li><a href="/docs/endpoint-authentication/permission-gating.html">Permission Gating</a>: restrict endpoints by the user&#39;s permissions</li><li><a href="/docs/mcp-servers/permissions.html">MCP Permissions</a>: permission-aware MCP tools that call downstream APIs as the user</li></ul>`,48),d=[r];function c(l,h,p,g,u,k){return n(),t("div",null,d)}const y=e(o,[["render",c]]);export{b as __pageData,y as default};
